package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamHumanBioBank2 {
  private const val T = "මානව දේහ ක්‍රියාවලි හා සෞඛ්‍යය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "මානව ජීව විද්‍යාවට අදාළ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("මානව ආමාශයෙන් ක්ෂුද්‍රාන්ත්‍රයේ ග්‍රහණියට ආහාර මුදා හැරීම පාලනය කරන මුදු පේශිය කුමක්ද?", "ජඨර නිර්ගම මුදු පේශිය", "හෘද මුදු පේශිය", "ප්‍රාචීරය", "අපිජිහ්විකාව", "අර්ධ වශයෙන් ජීර්ණය වූ ආම්ලික ආහාර ටිකෙන් ටික ග්‍රහණියට ඇතුළු වේ."),
    q("ප්‍රෝටීන ජීර්ණයේ අවසාන ඵලය ලෙස ක්ෂුද්‍රාන්ත්‍රයේදී ලැබෙන කුඩාම අණු මොනවාද?", "ඇමයිනෝ අම්ල", "පොලිපෙප්ටයිඩ", "මේද අම්ල", "ග්ලූකෝස්", "ඇමයිනෝ අම්ල රුධිර කේශනාලිකා තුළට අවශෝෂණය වී ප්‍රතිහාර ශිරාව ඔස්සේ අක්මාවට යයි."),
    q("ක්ෂුද්‍රාන්ත්‍රයේ සිට පෝෂ්‍ය පදාර්ථ රැගෙන යන රුධිරය ප්‍රථමයෙන්ම ගමන් කරන්නේ කුමන අවයවය වෙතද?", "අක්මාව වෙත (අක්මාවේ ප්‍රතිහාර ශිරාව ඔස්සේ)", "පෙනහැලි වෙත", "වකුගඩු වෙත", "මොළය වෙත", "අක්මාව මඟින් ග්ලූකෝස් මට්ටම පාලනය හා විෂ ද්‍රව්‍ය හරණය සිදු කරයි."),
    q("මානව ජීර්ණ පද්ධතියේ ඇපෙන්ඩික්සය (උණ්ඩුකපුච්ඡය) පිහිටා ඇත්තේ කුමන ස්ථානයේද?", "ක්ෂුද්‍රාන්ත්‍රය හා මහාන්ත්‍රය සම්බන්ධ වන ස්ථානයේ", "ආමාශය හා ග්‍රහණිය අතර", "ගලනාලය හා ආමාශය අතර", "ගුද මාර්ගයේ අග්‍රයේ", "උණ්ඩුකපුච්ඡයේ ආසාදනය ඇපෙන්ඩිසයිටිස් නම් වේ."),
    q("ආශ්වාස වාතය හා සසඳන විට ප්‍රශ්වාස වාතයේ උෂ්ණත්වය හා ජල වාෂ්ප ප්‍රමාණය පිළිබඳ නිවැරදි ප්‍රකාශය කුමක්ද?", "උෂ්ණත්වය හා ජල වාෂ්ප ප්‍රමාණය දෙකම වැඩිය", "උෂ්ණත්වය අඩු වී ජල වාෂ්ප වැඩි වේ", "ජල වාෂ්ප අඩු වී වියළි වේ", "දෙකම නොවෙනස්ව පවතී", "ප්‍රශ්වාස වාතය ජල වාෂ්පවලින් සංතෘප්ත වී ඇත."),
    q("හුණු දියර (කැල්සියම් හයිඩ්‍රොක්සයිඩ්) තුළින් ප්‍රශ්වාස වාතය බුබුලනය කළ විට කිරි පැහැ ගැන්වෙන්නේ කුමන වායුව නිසාද?", "කාබන් ඩයොක්සයිඩ්", "ඔක්සිජන්", "නයිට්‍රජන්", "ජල වාෂ්ප", "CO₂ හුණු දියර සමඟ ප්‍රතික්‍රියා කර අද්‍රාව්‍ය කැල්සියම් කාබනේට් සාදයි."),
    q("නිරෝගී වැඩිහිටියෙකුගේ විවේක අවස්ථාවේදී මිනිත්තුවකට සිදුවන ආසන්න ශ්වසන වාර ගණන කීයද?", "12–18 වාරයක්", "72–80 වාරයක්", "2–4 වාරයක්", "40–50 වාරයක්", "ව්‍යායාම කරන විට ශ්වසන වේගය හා ගැඹුර වැඩි වේ."),
    q("මිනිස් රුධිරයේ සාමාන්‍යයෙන් වැඩිම සංඛ්‍යාවකින් අඩංගු වන රුධිර සෛල වර්ගය කුමක්ද?", "රතු රුධිරාණු", "සුදු රුධිරාණු", "වසා සෛල", "නියුට්‍රොෆිල", "රුධිර ඝන මිලිමීටරයක රතු රුධිරාණු මිලියන 4.5–5.5 පමණ ඇත."),
    q("ශරීරයේ රුධිර හිඟයක් (නීරක්තිය) ඇති වූ විට රෝගියාට අධික ලෙස දැනෙන ප්‍රධාන ලක්ෂණය කුමක්ද?", "සුළු වෙහෙසකදී පවා ඉක්මනින් හතිය හා තෙහෙට්ටුව දැනීම", "දෘෂ්ටිය තියුණු වීම", "ශරීර බර ඉතා වේගයෙන් වැඩි වීම", "අධික උණ ගැනීම", "පටකවලට ප්‍රමාණවත් ඔක්සිජන් නොලැබීම ඊට හේතුවයි."),
    q("හෘදයටම ඔක්සිජන් හා පෝෂණය සපයන හෘද බිත්තිය මත පිහිටි රුධිර නාල මොනවාද?", "කොරොනරි ධමනි", "පුප්ඵුශීය ධමනි", "වෘක්ක ධමනි", "කැරොටිඩ් ධමනි", "කොරොනරි ධමනි මහා ධමනියේ ආරම්භයෙන්ම පැන නගී."),
    q("අපේ දේහයේ පටක අතරට රුධිර කේශනාලිකාවලින් කාන්දු වන තරලය නැවත රුධිර සංසරණයට එකතු කරන පද්ධතිය කුමක්ද?", "වසා පද්ධතිය", "ස්නායු පද්ධතිය", "බහිස්ස්‍රාවී පද්ධතිය", "ජීර්ණ පද්ධතිය", "වසා ගැටිති රෝග කාරක පෙරා දේහ ආරක්ෂාවට ද දායක වේ."),
    q("රුධිරයේ කැටි ගැසීමේදී දිය වී ඇති ෆයිබ්‍රිනොජන් අද්‍රාව්‍ය තන්තු බවට පත් කරන එන්සයිමය කුමක්ද?", "ත්‍රොම්බින්", "පෙප්සින්", "ටයලින්", "ලයිපේස්", "ත්‍රොම්බින් මඟින් ෆයිබ්‍රින් ජාලයක් සාදා රතු රුධිරාණු රඳවා කැටිය සාදයි."),
    q("පටක තරලය පිරිසිදු කරමින් රෝග කාරක විනාශ කරන වසා ගැටිති බහුලව පිහිටි ස්ථාන මොනවාද?", "බෙල්ල, කිහිලි සහ ඉකිලි ප්‍රදේශ", "අත්ල සහ පතුල", "හිස්කබල ඇතුළත", "නියපොතු පාදය", "ආසාදනයකදී මෙම වසා ගැටිති ඉදිමී වේදනාකාරී වේ (කුද්දැටි)."),
    q("මිනිසාගේ බහිස්ස්‍රාවී අවයවයක් ලෙස පෙනහැලි මඟින් බැහැර කරන ප්‍රධාන පරිවෘත්තීය අපද්‍රව්‍ය මොනවාද?", "කාබන් ඩයොක්සයිඩ් සහ ජල වාෂ්ප", "යූරියා සහ ලවණ", "පිත් වර්ණක", "මළ ද්‍රව්‍ය", "ශ්වසන පද්ධතිය බහිස්ස්‍රාවයට ද සෘජුව දායක වේ."),
    q("වකුගඩුවල හරස්කඩක පිටත රතු-දුඹුරු ප්‍රදේශය සහ ඇතුළත පිරමීඩාකාර ප්‍රදේශය පිළිවෙළින් හඳුන්වන්නේ කෙසේද?", "බාහිකය සහ මජ්ජාව", "ශ්‍රෝණිය සහ මූත්‍ර වාහිනිය", "බෝමන් ප්‍රාවරය සහ හෙන්ලේ පුඩුව", "මජ්ජාව සහ උච්චර්මය", "ග්ලෝමෙරුලස් බාහිකයේ පිහිටන අතර හෙන්ලේ පුඩු මජ්ජාවට විහිදේ."),
    q("මානව වකුගඩුවල ගල් (Kidney stones) සෑදීමට ප්‍රධාන වශයෙන් හේතු වන පුරුද්ද කුමක්ද?", "දිනපතා ප්‍රමාණවත් තරම් පිරිසිදු ජලය පානය නොකිරීම", "පළතුරු අනුභව කිරීම", "ව්‍යායාම කිරීම", "විටමින් C ගැනීම", "කැල්සියම් ඔක්සලේට් හා යූරික් අම්ල ස්ඵටික සාන්ද්‍ර මුත්‍රවල තැන්පත් වේ."),
    q("වකුගඩු අකර්මණ්‍ය වූ රෝගියෙකුගේ රුධිරයේ ඇති යූරියා හා අපද්‍රව්‍ය කෘත්‍රිමව පෙරා ඉවත් කිරීමේ ප්‍රතිකාරය කුමක්ද?", "රුධිර කාන්දු පෙරණය (Dialysis)", "රුධිර පාරවිලයනය", "ප්‍රතිශක්තිකරණය", "එක්ස්-කිරණ ප්‍රතිකාරය", "රුධිර කාන්දු පෙරණයේදී අර්ධ පාරගම්‍ය පටලයක් හරහා විසරණයෙන් යූරියා ඉවත් කෙරේ."),
    q("මිනිසාගේ ශරීරයේ විශාලතම අභ්‍යන්තර අවයවය මෙන්ම ග්ලයිකෝජන් ගබඩා කරන අවයවය කුමක්ද?", "අක්මාව", "වකුගඩුව", "ප්ලීහාව", "ආමාශය", "අක්මාවේ කාර්යයන් 500 කට අධික සංඛ්‍යාවක් පවතී."),
    q("ස්වයං සාධක ස්නායු පද්ධතිය මඟින් ප්‍රධාන වශයෙන් පාලනය කෙරෙන්නේ කුමන ක්‍රියාද?", "අනිච්ඡානුග අභ්‍යන්තර අවයව ක්‍රියාකාරිත්වය", "අත් පා වේගයෙන් සෙලවීම", "පාඩම් කිරීම හා කියවීම", "කතා කිරීම", "අනුවේගී හා ප්‍රත්‍යානුවේගී ලෙස කොටස් දෙකකින් සමන්විතය."),
    q("ස්නායු සෛලයක වෙනත් සෛලවලින් ආවේග ලබාගෙන සෛල දේහය වෙත ගෙන එන කෙටි අතු බෙදුණු ප්‍රසර මොනවාද?", "ඩෙන්ඩ්‍රයිට (Dendrites)", "ඇක්සන", "රැන්වියර් ගැට", "කණ්ඩරා", "බහුධ්‍රැවී නියුරෝනවල ඩෙන්ඩ්‍රයිට රාශියක් පිහිටයි."),
    q("විදුලි පන්දමක ආලෝකය ඇසට වැටුණු විගස කණිනිකාව කුඩා වීමේ ක්‍රියාව හඳුන්වන්නේ කුමන ප්‍රතීකයක් ලෙසද?", "කපාල ප්‍රතීක ක්‍රියාව", "සුෂුම්නා ප්‍රතීක ක්‍රියාව", "ඉච්ඡානුග ක්‍රියාව", "සමායෝජනය", "ඇසිපිය ගැසීම හා කණිනිකා ප්‍රතීකය මොළය හරහා සිදුවේ."),
    q("දෘෂ්ටි විතානයේ දිවා කාලයේදී වඩාත් පැහැදිලි හා තියුණු වර්ණ පෙනීමක් ලබාදෙන කේතු සෛල බහුලම ප්‍රදේශය කුමක්ද?", "කහ ලපය (Fovea / Yellow spot)", "අන්ධ බින්දුව", "තාරා මණ්ඩලය", "අක්ෂි කාචය", "කියවීමේදී අකුරු නාභිගත වන්නේ කහ ලපය මතයි."),
    q("වයස්ගත වීමත් සමඟ ඇසේ කාචය අපාරදෘශ්‍ය (සුදු පැහැති) වීම නිසා ඇතිවන රෝගී තත්ත්වය කුමක්ද?", "ඇසේ සුද (Cataract)", "ග්ලූකෝමා", "වර්ණ අන්ධතාව", "රාත්‍රී අන්ධතාව", "ශල්‍යකර්මයකින් අපාරදෘශ්‍ය කාචය ඉවත් කර කෘත්‍රිම කාචයක් දැමීමෙන් සුව කළ හැක."),
    q("ඇසේ අක්ෂි ගෝලයේ හැඩය පවත්වා ගැනීමට කාචයට පිටුපසින් පිරී ඇති ජෙලි වැනි තරලය කුමක්ද?", "කචාභ රසය (Vitreous humour)", "තාරා රසය (Aqueous humour)", "කඳුළු", "වසා තරලය", "කාචයට ඉදිරියෙන් තාරා රසය පිහිටා ඇත."),
    q("මිනිස් දිවේ අග්‍රයේ වඩාත්ම සංවේදී වන්නේ කුමන රසය සඳහාද?", "පැණි රස හා ලුණු රස", "තිත්ත රස", "ඇඹුල් රස", "මිරිස් රස", "දිවේ පසුපස කොටස තිත්ත රසට වැඩි සංවේදීතාවක් දක්වයි (රස අංකුර මුළු දිවේම පවතී)."),
    q("දිවේ සහ නාසයේ ඇති රස හා ගඳ සුවඳ හඳුනාගන්නා ප්‍රතිග්‍රාහක කුමන ප්‍රතිග්‍රාහක කාණ්ඩයට අයත් වේද?", "රසායනික ප්‍රතිග්‍රාහක (Chemoreceptors)", "තාප ප්‍රතිග්‍රාහක", "ප්‍රකාශ ප්‍රතිග්‍රාහක", "යාන්ත්‍රික ප්‍රතිග්‍රාහක", "ජලයේ දියවන රසායනික අණු මඟින් රස අංකුර උත්තේජනය වේ."),
    q("මානව සමේ පීඩනය, ස්පර්ශය, වේදනාව හා උෂ්ණත්වය හඳුනාගන්නා සංවේදී ප්‍රතිග්‍රාහක පිහිටා ඇත්තේ කුමන ස්තරයේද?", "චර්මය (Dermis)", "මතුපිට මළ අපිචර්මය", "නියපොතු", "උච්චර්මය", "චර්මයේ රුධිර නාල, ස්වේද ග්‍රන්ථි හා ස්නායු අන්ත පිහිටා ඇත."),
    q("මානව චර්මයේ ඇති මෙලනින් වර්ණකයේ ප්‍රධාන කාර්යය කුමක්ද?", "සූර්යයාගේ පාරජම්බුල කිරණවලින් සම ආරක්ෂා කිරීම", "දහඩිය නිපදවීම", "රුධිරය කැටි ගැස්වීම", "තාපය ජනනය කිරීම", "මෙලනින් සමේ වර්ණය ද තීරණය කරයි."),
    q("අන්තඃශ්‍රාවී ග්‍රන්ථි සහ බහිශ්‍රාවී ග්‍රන්ථි අතර ප්‍රධාන වෙනස්කම කුමක්ද?", "අන්තඃශ්‍රාවී ග්‍රන්ථිවලට නාල නොමැති අතර ස්‍රාවයන් සෘජුව රුධිරයට මුදා හරී", "අන්තඃශ්‍රාවී ග්‍රන්ථි එන්සයිම නිපදවයි", "බහිශ්‍රාවී ග්‍රන්ථි හෝමෝන නිපදවයි", "බහිශ්‍රාවී ග්‍රන්ථිවලට නාල නොමැත", "ඛේට ග්‍රන්ථි හා ස්වේද ග්‍රන්ථි නාල සහිත බහිශ්‍රාවී ග්‍රන්ථි වේ."),
    q("අන්තඃශ්‍රාවී ග්‍රන්ථියක් මෙන්ම බහිශ්‍රාවී ග්‍රන්ථියක් ලෙසත් ක්‍රියා කරන ද්විත්ව කෘත්‍ය අවයවය කුමක්ද?", "අග්න්‍යාසය", "තයිරොයිඩ් ග්‍රන්ථිය", "පිටියුටරි ග්‍රන්ථිය", "ඛේට ග්‍රන්ථිය", "එය ඉන්සියුලින් හෝමෝනය රුධිරයටත් ජීර්ණ එන්සයිම නාලයක් මගින් ග්‍රහණියටත් යවයි."),
    q("පිටියුටරි ග්‍රන්ථියෙන් වර්ධක හෝමෝනය (GH) ළමා වියේදී අධික ලෙස ශ්‍රාවය වීම නිසා ඇතිවන තත්ත්වය කුමක්ද?", "යෝධත්වය (Gigantism)", "කුරු බව (Dwarfism)", "ගලගණ්ඩය", "දියවැඩියාව", "ළමා වියේදී අඩු වුවහොත් කුරු බව ඇතිවේ."),
    q("මිනිසාගේ සාමාන්‍ය රුධිරයේ සිටින සුදු රුධිරාණු වර්ග අතරින් විශාලතම සෛලය හා භක්ෂක ක්‍රියාව කරන්නේ කුමක්ද?", "මොනොසයිට", "බේසොෆිල", "ලිම්ෆොසයිට", "පට්ටිකා", "මොනොසයිට පටක තුළදී මැක්‍රොෆේජ බවට පත්වේ."),
    q("වකුගඩුවෙන් නිපදවන මුත්‍ර මුත්‍රාශය වෙත ගෙන යන නාල යුගලය කුමක්ද?", "මූත්‍ර වාහිනී (Ureters)", "මූත්‍ර මාර්ගය (Urethra)", "වෘක්ක ධමනි", "වෘක්ක ශිරා", "මුත්‍රාශයේ සිට පිටතට මුත්‍ර ගෙන යන්නේ මූත්‍ර මාර්ගයයි."),
    q("සාමාන්‍යයෙන් පිරිමි දරුවෙකු වැඩිවිය පැමිණීමේදී කටහඬ ගොරෝසු වීම හා රැවුල වැවීම සිදු වන්නේ කුමන හෝමෝනය නිසාද?", "ටෙස්ටොස්ටෙරෝන්", "ඊස්ට්‍රජන්", "ප්‍රොජෙස්ටරෝන්", "ඔක්සිටොසින්", "ටෙස්ටොස්ටෙරෝන් පුරුෂ ද්විතීයික ලිංගික ලක්ෂණ ඇති කරයි."),
    q("ස්ත්‍රී ආර්තව චක්‍රය සාමාන්‍යයෙන් දින කීයකට වරක් සිදුවන චක්‍රීය ක්‍රියාවලියක්ද?", "දින 28", "දින 7", "දින 14", "දින 60", "පළමු දින 4–5 ක කාලය ආර්තව අවධිය ලෙස හැඳින්වේ."),
    q("මව් කුස තුළ කළලය කම්පනවලින් ආරක්ෂා කරමින් වටකර ඇති තරලය කුමක්ද?", "උල්බ තරලය (Amniotic fluid)", "කඳුළු තරලය", "සන්ධි තරලය", "ප්ලූරා තරලය", "උල්බ තරලය කළලයට ඒකාකාර උෂ්ණත්වයක් හා නිදහස් වර්ධන ඉඩක් ලබා දෙයි."),
    q("ලිංගිකව සම්ප්‍රේෂණය වන රෝගයක් වන ඒඩ්ස් (AIDS) ඇති කරන රෝග කාරකයා මිනිස් දේහයේ විනාශ කරන්නේ කුමන සෛලද?", "සුදු රුධිරාණු (T-ලිම්ෆොසයිට)", "රතු රුධිරාණු", "අස්ථි සෛල", "පේශි සෛල", "HIV වෛරසය ප්‍රතිශක්තිකරණ පද්ධතිය දුර්වල කරයි."),
    q("ගොනෝරියා සහ සිපිලිස් යන ලිංගිකව සම්ප්‍රේෂණය වන රෝග ඇති කරන්නේ කුමන ක්ෂුද්‍රජීවී කාණ්ඩය මඟින්ද?", "බැක්ටීරියා", "වෛරස", "දිලීර", "ප්‍රොටොසෝවා", "බැක්ටීරියා රෝග ප්‍රතිජීවක මගින් මුල් අවධියේදී සුව කළ හැක."),
    q("මානව සැකිලි පද්ධතියේ වැදගත් කාර්යයක් නොවන්නේ කුමක්ද?", "හෝමෝන ශ්‍රාවය කිරීම", "දේහයට හැඩය හා ආධාරකය දීම", "අභ්‍යන්තර අවයව ආරක්ෂා කිරීම", "රුධිර සෛල නිපදවීම", "දිගු අස්ථිවල ඇට මිදුළු තුළ රතු හා සුදු රුධිරාණු නිපදවේ."),
    q("මිනිසාගේ ශරීර උෂ්ණත්වය අධික වූ විට තාපය පිට කිරීමට සමේ රුධිර නාලවලට කුමක් සිදුවේද?", "පෘෂ්ඨය ආසන්න රුධිර කේශනාලිකා ප්‍රසාරණය වීම", "රුධිර කේශනාලිකා සංකෝචනය වීම", "රෝම කෙළින් වීම", "වෙව්ලීම ඇතිවීම", "රුධිර ප්‍රවාහය වැඩි වීමෙන් විකිරණය හා සන්නයනය මඟින් තාපය පිටවේ."),
    q("ශීත කාලගුණයකදී මිනිස් දේහය අධිකව සිසිල් වන විට තාපය නිපදවීමට සිදුවන අනිච්ඡානුග ක්‍රියාව කුමක්ද?", "පේශි වෙව්ලීම", "දහඩිය දැමීම", "සමේ රුධිර නාල පුළුල් වීම", "හෘද ස්පන්දනය නැවතීම", "වෙව්ලීමේදී පේශි ශ්වසනයෙන් තාප ශක්තිය මුදා හරී."),
    q("අපේ සිරුරේ පිහිටි රිද්මයානුකූල චලනයක් පෙන්වන අනිච්ඡානුග නමුත් සිනිඳු පේශි නොවන පේශිය කුමක්ද?", "හෘත් පේශිය", "ද්විශීර්ෂ පේශිය", "ආමාශ පේශිය", "උදර බිත්ති පේශිය", "හෘත් පේශිවල තීර්යක් රේඛා හා අන්තර්ස්ථාපිත තැටි ඇත."),
    q("සන්ධියකදී අස්ථි කෙළවරවල් එකිනෙක ගැටීම හා ගෙවී යාම වළක්වන සිනිඳු පටක ස්තරය කුමක්ද?", "කාටිලේජය", "කණ්ඩරාව", "බන්ධනිය", "මේද පටකය", "සයිනෝවියල් තරලය ද සන්ධිය ලිහිසි කරයි."),
    q("දීර්ඝ කාලීනව අධික මත්පැන් පානය කිරීම නිසා ප්‍රධාන වශයෙන්ම විනාශ වී සිරෝසිස් ඇති වන අවයවය කුමක්ද?", "අක්මාව", "වකුගඩුව", "හෘදය", "පෙනහැලි", "අක්මා සෛල මැරී තන්තුමය පටක බවට හැරේ."),
    q("ජලභීතිකා රෝගය, ඉන්ෆ්ලුවෙන්සා සහ සරම්ප යන රෝග සියල්ල ඇති කරන ක්ෂුද්‍රජීවී වර්ගය කුමක්ද?", "වෛරස", "බැක්ටීරියා", "දිලීර", "ඇමීබා", "වෛරස රෝග සඳහා ප්‍රතිජීවක ඖෂධ ක්‍රියා නොකරයි."),
    q("විටමින් K නිපදවීමට හා ආහාර ජීර්ණයට සහය වෙමින් මිනිස් මහාන්ත්‍රයේ සහජීවීව වෙසෙන බැක්ටීරියාව කුමක්ද?", "එස්චෙරීෂියා කෝලයි (E. coli)", "රයිසෝබියම්", "මයිකොබැක්ටීරියම්", "විබ්‍රියෝ කොලරා", "අන්ත්‍රික බැක්ටීරියා මිනිසාට විටමින් K හා B₁₂ සපයයි."),
    q("ප්‍රථමාධාරයේදී විෂ සර්ප දෂ්ටනයකට ලක් වූ රෝගියෙකුට නොකළ යුතුම දෙය කුමක්ද?", "රෝගියා ඇවිද්දවීම හෝ තුවාලය කපා රුධිරය ඉරීම", "රෝගියා නිසලව තබා සන්සුන් කිරීම", "දෂ්ට කළ අවයවය හෘද මට්ටමට පහළින් තැබීම", "වහාම රෝහල්ගත කිරීම", "ඇවිදීමෙන් විෂ රුධිරය හරහා ඉක්මනින් ශරීරය පුරා පැතිරේ."),
    q("මානව මුඛ කුහරයේ පවතින ප්‍රධාන ඛේට ග්‍රන්ථි යුගල සංඛ්‍යාව කීයද?", "යුගල 3 කි", "යුගල 1 කි", "යුගල 6 කි", "යුගල 2 කි", "කර්ණමූල, අධෝහනු හා අධෝජිහ්ව ලෙස ග්‍රන්ථි යුගල තුනකි."),
    q("පුද්ගලයෙකුගේ ශරීර ස්කන්ධ දර්ශකය (BMI) ගණනය කරනු ලබන නිවැරදි සූත්‍රය කුමක්ද?", "ස්කන්ධය (kg) / [උස (m)]²", "උස (m) / ස්කන්ධය (kg)", "ස්කන්ධය (kg) × උස (m)", "[ස්කන්ධය (kg)]² / උස (m)", "18.5–24.9 අතර BMI අගය සෞඛ්‍ය සම්පන්න පරාසය ලෙස සැලකේ."),
    q("ගැබිනි මවකගේ ආහාරයේ අත්‍යවශ්‍යයෙන්ම ප්‍රමාණවත්ව තිබිය යුතු හා කළලයේ ස්නායු නාල වර්ධනයට උපකාරී වන විටමිනය කුමක්ද?", "ෆෝලික් අම්ලය (විටමින් B₉)", "විටමින් K", "විටමින් D", "විටමින් E", "වැඩි යකඩ හා ෆෝලික් අම්ල අවශ්‍යතාවක් ගර්භණී සමයේ පවතී."),
    q("මිනිසාගේ ස්වාසනාලය තුළ පවතින කේශාකාර ව්‍යුහ (පක්ෂ්ම) දුම්පානය නිසා අක්‍රිය වූ විට ඇතිවන ගැටලුව කුමක්ද?", "දූවිලි හා ශ්ලේෂ්මල පෙනහැලි තුළ එකතු වී නිතර කැස්ස ඇතිවීම", "හිමොග්ලොබින් වැඩිවීම", "වකුගඩු ගල් සෑදීම", "ආහාර ජීර්ණය නැවතීම", "දුම්පානය කරන්නන්ගේ පෙනහැලි ආසාදන වැඩි වීමට මෙය හේතුවකි."),
    q("ප්‍රතිශක්තිකරණයේදී ප්‍රතිදේහ නිපදවීමට සෘජුවම දායක වන සුදු රුධිරාණු විශේෂය කුමක්ද?", "B-ලිම්ෆොසයිට", "නියුට්‍රොෆිල", "රතු රුධිරාණු", "ඉයෝසිනොෆිල", "B-ලිම්ෆොසයිට ප්ලාස්මා සෛල බවට පත්වී ප්‍රතිදේහ නිපදවයි."),
    q("රෝගී වූ විට දේහයේ උෂ්ණත්වය ඉහළ ගොස් උණ ඇති වීමෙන් දේහයට ලැබෙන ආරක්ෂක වාසිය කුමක්ද?", "රෝග කාරක බැක්ටීරියා වර්ධනය අඩාල වී ප්‍රතිශක්ති සෛල ක්‍රියාව වේගවත් වීම", "රතු රුධිරාණු වැඩි වීම", "ආහාර ජීර්ණය නැවැත්වීම", "හෘද ස්පන්දනය නැවැත්වීම", "අධික උණ (41°C ඉක්මවීම) මොළයට අහිතකර බැවින් පාලනය කළ යුතුය."),
    q("රුධිර කාණ්ඩවල 'Rh සාධකය' (Rh⁺ හෝ Rh⁻) නොගැළපීම බරපතල ගැටලුවක් විය හැක්කේ කුමන අවස්ථාවේදීද?", "Rh⁻ මවකට දෙවන Rh⁺ දරුවෙකු පිළිසිඳ ගැනීමේදී", "Rh⁺ මවකට Rh⁻ දරුවෙකු ලැබීමේදී", "මව හා පියා දෙදෙනාම Rh⁺ විට", "දරුවා O⁺ වූ විට", "මවගේ ප්‍රති-Rh ප්‍රතිදේහ දෙවන දරුවාගේ රතු රුධිරාණු බිඳ දැමිය හැක."),
    q("මානව ශ්‍රවණ සංවේදනයේදී වාතය හරහා පැමිණෙන ශබ්ද තරංග මුලින්ම කම්පනය කරන්නේ කුමන පටලයද?", "කර්ණ පටහ පටලය (Eardrum)", "දෘෂ්ටි විතානය", "ප්ලූරාව", "අණ්ඩාකාර ජනේලය", "කර්ණ පටහ පටලය බාහිර කණ හා මැද කණ වෙන් කරයි."),
    q("ශ්‍රවණ හැකියාව ඇති සාමාන්‍ය මිනිස් කණට ඇසෙන ශබ්ද සංඛ්‍යාත පරාසය කුමක්ද?", "20 Hz – 20,000 Hz", "0 Hz – 10 Hz", "50,000 Hz – 100,000 Hz", "5 Hz – 100 Hz", "20,000 Hz ට වැඩි සංඛ්‍යාත අතිධ්වනි තරංග ලෙස හැඳින්වේ."),
    q("වකුගඩුවල හෙන්ලේ පුඩුවේ ප්‍රධාන කාර්යය කුමක්ද?", "සාන්ද්‍ර මුත්‍ර සෑදීම සඳහා ජලය හා ලවණ නැවත අවශෝෂණය කිරීම", "රුධිර සෛල පෙරීම", "ග්ලූකෝස් නිපදවීම", "ඇමෝනියා සෑදීම", "කාන්තාර සතුන්ගේ හෙන්ලේ පුඩුව ඉතා දිගු වේ."),
    q("කුසගින්න දැනෙන විට හා ආහාර ගත් පසු ආමාශයෙන් ඉන්සියුලින් මට්ටම කෙරෙහි ඇති වන බලපෑම කුමක්ද?", "ආහාර ගත් පසු රුධිර ග්ලූකෝස් වැඩි වී ඉන්සියුලින් ශ්‍රාවය වැඩි වේ", "ආහාර ගත් පසු ඉන්සියුලින් ශුන්‍ය වේ", "කුසගින්නේදී ඉන්සියුලින් උපරිම වේ", "ආහාර හා ඉන්සියුලින් අතර සබඳතාවක් නැත", "නියත රුධිර ග්ලූකෝස් මට්ටමක් පවත්වා ගැනීම සමස්ථිතියකි."),
    q("අප දකින හා අසන දේවල් මතකයේ තබා ගැනීම හා තර්කානුකූලව සිතීම සිදු කරන්නේ මොළයේ කුමන ප්‍රදේශය මගින්ද?", "මස්තිෂ්ක බාහිකය", "සුෂුම්නා ශීර්ෂකය", "අනුමස්තිෂ්කය", "පෝන්ස්", "මස්තිෂ්ක බාහිකය නැමි හා කට්ටා රාශියකින් සමන්විත වී පෘෂ්ඨය වැඩි කර ඇත."),
    q("පුද්ගලයෙකුගේ පෙනහැලි තුළට උපරිම ආශ්වාසයකින් පසු පිට කළ හැකි උපරිම වායු පරිමාව හඳුන්වන්නේ කෙසේද?", "ජීව ධාරිතාව (Vital capacity)", "ප්‍රවාහන පරිමාව", "ශේෂ පරිමාව", "රුධිර පරිමාව", "ක්‍රීඩකයන්ගේ ජීව ධාරිතාව සාමාන්‍ය අයෙකුට වඩා වැඩිය."),
    q("රතු රුධිරාණු ජීවිත කාලය (දින 120 පමණ) අවසානයේදී විනාශ කර දමනු ලබන්නේ කුමන අවයවවලදීද?", "ප්ලීහාව සහ අක්මාව", "වකුගඩුව සහ පෙනහැලි", "ආමාශය සහ ග්‍රහණිය", "මොළය සහ හෘදය", "හිමොග්ලොබින්වල ඇති යකඩ නැවත භාවිතයට ගබඩා කෙරේ."),
    q("මානව ජීර්ණයේදී තන්තු (සෙලියුලෝස්) ජීර්ණය කිරීමට අවශ්‍ය එන්සයිමය කුමක්ද?", "මිනිසා සතුව සෙලියුලේස් එන්සයිමය නොමැත", "පෙප්සින්", "ට්‍රිප්සින්", "ලයිපේස්", "ශාක භක්ෂක ගවයන්ගේ ආමාශයේ සිටින බැක්ටීරියා සෙලියුලේස් නිපදවයි."),
    q("මානව දේහයේ ඇති දිගම හා ශක්තිමත්ම අස්ථිය කුමක්ද?", "ඌර්වස්ථිය (කළවා අස්ථිය / Femur)", "ප්‍රගණ්ඩාස්ථිය", "ධරණකය", "පර්ශු අස්ථිය", "ශරීරයේ කුඩාම අස්ථිය මැද කණේ ඇති ධරණකය (Stapes) වේ."),
    q("හදිසි හුස්ම ගැනීමේ අපහසුතාවක් ඇතිවිට ස්වසන නාලිකා පටු වී ශ්වසන ශබ්ද ඇති වන නිදන්ගත රෝගය කුමක්ද?", "ඇදුම (Asthma)", "වකුගඩු රෝගය", "පිළිකා", "ක්ෂය රෝගය", "දූවිලි, පරාග හා දුම් ඇදුම උත්සන්න කළ හැක."),
    q("හෘද රෝග ඇති පුද්ගලයෙකුගේ හෘදයේ විද්‍යුත් ක්‍රියාකාරිත්වය සටහන් කර ගැනීමට කරන පරීක්ෂණය කුමක්ද?", "විද්‍යුත් හෘද සටහන (ECG)", "EEG පරීක්ෂණය", "X-කිරණ", "අල්ට්‍රාසවුන්ඩ් ස්කෑන්", "ECG මගින් හෘද කුටීරවල විද්‍යුත් ආවේග පරීක්ෂා කරයි."),
    q("රෝගියෙකුගේ මොළයේ විද්‍යුත් ක්‍රියාකාරිත්වය මැනීමට යොදා ගන්නා වෛද්‍ය පරීක්ෂණය කුමක්ද?", "විද්‍යුත් මස්තිෂ්ක සටහන (EEG)", "ECG", "RBC ගණනය", "ESR පරීක්ෂණය", "අපස්මාරය වැනි රෝග හඳුනා ගැනීමට EEG භාවිත කෙරේ."),
    q("මිනිසාගේ වමන ප්‍රතීකය, කැස්ස හා ගිලීම පාලනය වන්නේ මොළයේ කුමන කොටස මඟින්ද?", "සුෂුම්නා ශීර්ෂකය", "මස්තිෂ්කය", "අනුමස්තිෂ්කය", "පිටියුටරිය", "සුෂුම්නා ශීර්ෂකය අත්‍යවශ්‍ය අනිච්ඡානුග ප්‍රතීක රැසක් පාලනය කරයි."),
    q("පළමු වරට රුධිර සංසරණ පද්ධතියේ ක්‍රියාකාරීත්වය විද්‍යාත්මකව විස්තර කළ විද්‍යාඥයා කවුද?", "විලියම් හාවි", "ලුවී පාස්චර්", "එඩ්වඩ් ජෙනර්", "රොබට් කොක්", "හෘදය පොම්පයක් ලෙස ක්‍රියා කරන බව හාවි පෙන්වා දුන්නේය."),
    q("වසූරිය රෝගයට එරෙහිව ලොව ප්‍රථම එන්නත සොයා ගත් විද්‍යාඥයා කවුද?", "එඩ්වඩ් ජෙනර්", "ලුවී පාස්චර්", "ඇලෙක්සැන්ඩර් ෆ්ලෙමින්", "ග්‍රෙගර් මෙන්ඩල්", "ගව වසූරිය ආසාදනයෙන් මානව වසූරිය වැළැක්විය හැකි බව ජෙනර් සොයා ගත්තේය."),
    q("දරුණු බැක්ටීරියා ආසාදනයක් වන ක්ෂය රෝගය (TB) ඇති කරන රෝග කාරකයා මිනිස් දේහයට ඇතුළු වන්නේ කෙසේද?", "රෝගියාගේ කැස්ස හා කිවිසුම් හරහා වාතයෙන්", "මදුරුවන්ගෙන්", "මීයන්ගෙන්", "සූර්යාලෝකයෙන්", "ක්ෂය රෝගය මයිකොබැක්ටීරියම් ටියුබර්කියුලෝසිස් බැක්ටීරියාවෙන් සෑදේ."),
    q("සාමාන්‍යයෙන් පුරුෂයෙකුගේ ජන්මාණු නිෂ්පාදන වේගය අඛණ්ඩව පැවතුණද ස්ත්‍රියකගේ මසකට පරිණත වන ඩිම්බ සංඛ්‍යාව සාමාන්‍යයෙන් කීයද?", "1 කි", "20 කි", "මිලියන 1 කි", "100 කි", "එක් ආර්තව චක්‍රයකදී එක් ඩිම්බයක් මෝචනය වේ."),
    q("පැලෝපීය නාලයේදී සංසේචනය වූ යුක්තාණුව සෛල බෙදීමට ලක් වී ගර්භාෂ බිත්තියේ තැන්පත් වන අවස්ථාව කුමක්ද?", "අධිරෝපණය (Implantation)", "ඩිම්බ මෝචනය", "සංසේචනය", "ආර්තවය", "අධිරෝපණය සංසේචනයෙන් දින 7 කට පමණ පසු සිදුවේ."),
    q("ශරීරය තුළ පිහිටි රුධිර නාල අතුරින් රුධිර පීඩනය වැඩිම හා ඝන ප්‍රත්‍යාස්ථ බිත්ති ඇති නාලය කුමක්ද?", "ධමනි", "ශිරා", "කේශනාලිකා", "වසා නාල", "හෘදයෙන් පොම්ප කරන අධික පීඩනයට ඔරොත්තු දීමට ධමනි බිත්ති ඝන වේ."),
    q("දේහයේ බාහිර පරිසරයේ සිදුවන වෙනස්වීම්වලට අනුව දේහ අභ්‍යන්තර පරිසරය නියතව පවත්වා ගැනීම හඳුන්වන්නේ කුමන නමින්ද?", "සමස්ථිතිය (Homeostasis)", "විකසනය", "පරිණාමය", "ප්‍රතිශක්තිය", "උෂ්ණත්වය, ජල මට්ටම හා ග්ලූකෝස් මට්ටම සමස්ථිතිය මඟින් පාලනය වේ."),
    q("අධික රුධිර පීඩනය (Hypertension) ඇති පුද්ගලයෙකු ආහාරයේදී සීමා කළ යුතු ප්‍රධාන ඛනිජ සංයෝගය කුමක්ද?", "සෝඩියම් ක්ලෝරයිඩ් (ලුණු)", "පොටෑසියම්", "විටමින් C", "තන්තු", "අධික ලුණු රුධිරයේ ජලය රඳවා තබා රුධිර පීඩනය ඉහළ දමයි."),
    q("අක්මාවේ සිට පිත ග්‍රහණිය වෙත රැගෙන යන නාල පද්ධතිය අවහිර වුවහොත් ඇසේ සුදු පැහැ කොටස කහ වන රෝග ලක්ෂණය කුමක්ද?", "සෙංගමාලය (Jaundice)", "රක්තහීනතාව", "ස්කර්වි", "බෙරිබෙරි", "පිත් වර්ණක (බිලිරුබින්) රුධිරයේ එකතු වීමෙන් සම හා ඇස් කහ පැහැ ගැන්වේ."),
    q("වකුගඩුවට අපිරිසිදු රුධිරය ගෙන එන රුධිර නාලය හා පිරිසිදු කළ රුධිරය ගෙන යන නාලය පිළිවෙළින් කුමක්ද?", "වෘක්ක ධමනිය හා වෘක්ක ශිරාව", "මහා ශිරාව හා මහා ධමනිය", "පුප්ඵුශීය ධමනිය හා ශිරාව", "කොරොනරි ධමනිය හා ශිරාව", "වෘක්ක ශිරාවේ යූරියා ප්‍රමාණය ඉතා අඩුය."),
    q("රෝගීන්ට අධික ලෙස ප්‍රතිජීවක (Antibiotics) අනවශ්‍ය ලෙස භාවිත කිරීමේ ප්‍රධාන අවාසිය කුමක්ද?", "බැක්ටීරියාවල ප්‍රතිජීවක ප්‍රතිරෝධීතාව (Resistance) ඇතිවීම", "වෛරස සංඛ්‍යාව ඉක්මනින් අඩු වීම", "ශරීරය ශක්තිමත් වීම", "හිමොග්ලොබින් වැඩි වීම", "ප්‍රතිජීවක වෛද්‍ය උපදෙස් මත නියමිත කාලය සම්පූර්ණ වන තෙක් ගත යුතුය."),
    q("ස්නායු ආවේග සම්ප්‍රේෂණය වේගවත් කරන ඇක්සනය වටා පිහිටි ලිපිඩමය පරිවාරක ආවරණය කුමක්ද?", "මයලින් කොපුව", "සෛල බිත්තිය", "ප්ලූරාව", "ටෝනොප්ලාස්ටය", "රැන්වියර් ගැට අතරින් ආවේග පැන පැන ගමන් කිරීමෙන් වේගය වැඩි වේ."),
    q("දේහයේ ඇති රුධිර නාල අතරින් පටක සෛල හා රුධිරය අතර ඔක්සිජන් හුවමාරුව සිදුවන්නේ කුමන නාල හරහා පමණක්ද?", "රුධිර කේශනාලිකා", "ධමනි", "ශිරා", "මහා ධමනිය", "ධමනි හා ශිරා බිත්ති ඝන නිසා ඒවා හරහා වායු හුවමාරු නොවේ."),
    q("වකුගඩුවේ බෝමන් ප්‍රාවරය තුළ පවතින ඉතා සියුම් රුධිර කේශනාලිකා ජාලය හඳුන්වන්නේ කුමන නමින්ද?", "ග්ලෝමෙරුලසය (Glomerulus)", "හෙන්ලේ පුඩුව", "සංග්‍රාහක නාලය", "අංගුලිකාව", "අභිවාහී ධමනිකාව පළල් හා අපවාහී ධමනිකාව පටු බැවින් අධික පෙරීමේ පීඩනයක් ඇතිවේ."),
    q("මානව අස්ථි සෛලවලට අවශ්‍ය දෘඪතාව ලබා දෙන අකාබනික ලවණය කුමක්ද?", "කැල්සියම් පොස්පේට්", "සෝඩියම් ක්ලෝරයිඩ්", "පොටෑසියම් නයිට්‍රේට්", "මැග්නීසියම් සල්ෆේට්", "කොලැජන් තන්තු අස්ථියට නම්‍යශීලීත්වය ද කැල්සියම් ලවණ දෘඪ බව ද ලබා දෙයි."),
    q("සජීවී මිනිස් සෛල අතරින් විශේෂිත වූ දිගම සෛලය ලෙස සැලකෙන්නේ කුමක්ද?", "නියුරෝනය (ස්නායු සෛලය)", "රතු රුධිරාණුව", "අපිචර්ම සෛලය", "ඩිම්බය", "සුෂුම්නාවේ සිට පාදයේ ඇඟිලි දක්වා විහිදෙන ස්නායු සෛල මීටරයක් පමණ දිගු විය හැක."),
    q("පාසල් සිසුවෙකුට අධික රුධිර වහනයක් සහිත තුවාලයක් ඇති වූ විට මුලින්ම කළ යුතු ප්‍රථමාධාරය කුමක්ද?", "පිරිසිදු රෙදි කැබැල්ලකින් තුවාලය මත තදින් තෙරපා අල්ලා ගැනීම", "තුවාලය මත පස් දැමීම", "සීතල කෝපි වත් කිරීම", "තුවාලය සෙලවීම", "සෘජු පීඩනය යෙදීමෙන් රුධිරය කැටි ගැසීම ඉක්මන් වේ."),
    q("මානව ජීර්ණ පද්ධතියේ මේදය ජීර්ණය කරන ලයිපේස් එන්සයිමය ක්‍රියා කරන ප්‍රශස්ත pH පරාසය කුමක්ද?", "භාෂ්මික මාධ්‍යය (pH 7.5–8.5)", "දැඩි ආම්ලික මාධ්‍යය (pH 1.5)", "දැඩි භාෂ්මික (pH 13)", "pH 3", "අග්න්‍යාසයික යුෂයේ හා පිතේ ඇති බයිකාබනේට් මගින් ග්‍රහණිය භාෂ්මික කරයි."),
    q("දේහයේ අභ්‍යන්තර ජෛව ඔරලෝසුව හා නින්ද අවදි වීමේ රටාව පාලනය කරන මොළය ආශ්‍රිත ග්‍රන්ථිය කුමක්ද?", "පීනියල් ග්‍රන්ථිය", "තයිරොයිඩ් ග්‍රන්ථිය", "අධිවෘක්ක ග්‍රන්ථිය", "පැරාතයිරොයිඩ්", "පීනියල් ග්‍රන්ථිය මඟින් මෙලටොනින් හෝමෝනය ශ්‍රාවය කෙරේ."),
    q("රුධිරයේ කැල්සියම් මට්ටම ඉහළ නැංවීමට ක්‍රියා කරන අන්තඃශ්‍රාවී ග්‍රන්ථිය කුමක්ද?", "පැරාතයිරොයිඩ් ග්‍රන්ථිය", "අග්න්‍යාසය", "අධිවෘක්ක ග්‍රන්ථිය", "ඩිම්බකෝෂය", "තයිරොයිඩ් ග්‍රන්ථිය පිටුපස කුඩා පැරාතයිරොයිඩ් ග්‍රන්ථි හතරක් පිහිටයි."),
    q("හදිසි හෘදයාබාධයකදී හෘදය නතර වූ රෝගියෙකුගේ ජීවිතය බේරා ගැනීමට ලබා දෙන ක්ෂණික ප්‍රතිකාරය කුමක්ද?", "හෘත්-පුප්ඵුශීය පුනර්ජීවනය (CPR)", "සීනි වතුර පෙවීම", "තුවාල වෙළීම", "අයිස් තැබීම", "පපුව තෙරපීම හා කෘත්‍රිම ශ්වසනය මොළයට ඔක්සිජන් සැපයුම පවත්වා ගනී."),
    q("පිළිකා සෛල හා සාමාන්‍ය දේහ සෛල අතර ඇති ප්‍රධාන වෙනස්කම කුමක්ද?", "පිළිකා සෛල පාලනයකින් තොරව අසීමිතව විභාජනය වීම", "පිළිකා සෛලවල DNA නොතිබීම", "පිළිකා සෛල කිසිවිටෙක නොබෙදීම", "පිළිකා සෛල ශ්වසනය නොකිරීම", "අසාමාන්‍ය සෛල විභාජනය නිසා ගෙඩි (Tumours) සෑදේ.")
  )
}
